import"./chunk-2NFLSA4Y.js";var a={singularity:{theory:{concept:"[[In general relativity, a singularity is a place where the classical description of spacetime breaks down: the curvature of spacetime grows without limit and the equations no longer make predictions.]] Inside a non-rotating black hole the centre, r = 0, is such a singularity. Once a body has crossed the event horizon, it reaches the singularity within a finite time on its own clock, whatever it does. Physicists expect that a quantum theory of gravity, which does not yet exist, will replace this description near the singularity, so the calculation here stops before it."},section:{horizon:{title:"Horizon and centre",text:"[[The event horizon at r = R\u209B is not the singularity.]] Curvature is finite there. In the classical Schwarzschild solution, curvature grows without bound as r approaches zero."},fall:{title:"The falling clock",text:"The animation follows radial free fall with the inward speed acquired by falling from rest at infinity. Proper time is the time measured by the falling particle. [[Crossing the horizon takes finite proper time.]]"},limit:{title:"Where the model ends",text:"The central marker represents r = 0; it is not a material ball. The calculation stops at 0.1 R\u209B. Quantum gravity may change the classical prediction; this simulation cannot determine what happens at the singularity."}},param:{mass:"Mass (solar masses)",start:"Starting radius / R\u209B",playback:"Proper milliseconds per playback second",timeStep:"Playback timestep"},hint:{mass:"One solar mass is the mass of the Sun. A larger mass makes the horizon larger.",start:"The initial inward speed is set by free fall from infinity, not by release from rest here.",playback:"This changes playback speed only. The physical trajectory is unchanged."},preset:{small:"3 solar masses",large:"30 solar masses"},measure:{radiusRatio:"Radius / horizon radius",horizonRadius:"Horizon radius",properTime:"Elapsed proper time",curvatureRatio:"Curvature relative to the horizon",horizonTime:"Proper time to the horizon"},graph:{radius:"Radius vs playback time",curvature:"Curvature growth vs playback time",log:"log\u2081\u2080(K/K at horizon)"},view:{horizon:"Event horizon \xB7 r = R\u209B",center:"r = 0 \xB7 classical singularity",outside:"Test particle outside the horizon",inside:"Test particle inside the horizon",stopped:"Stopped at 0.1 R\u209B \xB7 centre not simulated",drawing:"Schematic cutaway \xB7 slowed playback",path:"Radial path"},formula:{horizon:"Schwarzschild radius",fall:"Radial free fall, E = 1",curvature:"Spacetime curvature (Kretschmann invariant)"},variable:{mass:"Black-hole mass in solar masses",radius:"Radius relative to the horizon",proper:"Time on the falling clock",curvature:"Curvature divided by its horizon value"},assumption:{hole:"An isolated, nonrotating, uncharged Schwarzschild black hole.",particle:"A point test particle with no angular momentum; its gravity, radiation and quantum effects are ignored.",initial:"Initial inward motion corresponds to falling from rest at infinity (E = 1).",drawing:"The wireframe is a coordinate cutaway, not an optical view or a physical shell. Marker sizes are not to scale; lengths use R\u209B units.",playback:"Playback seconds are converted to proper time at the selected rate. Graph time is playback time, not distant-observer time.",stop:"The calculation stops at r = 0.1 R\u209B, a chosen numerical boundary, not a physical surface. It never evaluates r = 0."},challenge:{cross:{title:"Cross the horizon",description:"Let the particle reach r < R\u209B.",hint:"Start the animation and watch the radius ratio fall below 1."},deep:{title:"Explore the interior",description:"Reach r \u2264 0.5 R\u209B.",hint:"Continue after crossing the horizon."},large:{title:"A larger horizon",description:"Build a black hole with a horizon radius of at least 60 km.",hint:"Increase the mass."},curvature:{title:"64 times the curvature",description:"Reach curvature at least 64 times its horizon value.",hint:"Curvature grows as the inverse sixth power of radius."}}}},i={sim:a};export{i as default,a as sim};
